// Shared bitmap text presets for the journey and embedded levels.
(()=>{
 const key='peninsula-text-presets-v1';
 const names={large:'Большой текст',small:'Малый текст',technical:'Технический текст',heading:'Заголовок'};
 const roles={narrator:'Текст рассказчика',dialogue:'Диалог',situation:'Ситуация',mapFooter:'Текст внизу карты',question:'Текст вопроса',firstScreen:'Текст на первом экране'};
 const defaults={assignments:{narrator:'large',dialogue:'large',situation:'small',mapFooter:'small',question:'large',firstScreen:'large'},presets:{}};
 for(const [id,size]of Object.entries({large:13,small:10,technical:8,heading:16}))defaults.presets[id]={size,align:id==='heading'?'center':'left',padding:5,offset:0,uppercase:false,color:'#bec4c9'};
 const clamp=(v,a,b,d)=>Number.isFinite(Number(v))?Math.round(Math.max(a,Math.min(b,Number(v)))):d;
 function normalize(value={}){const out=JSON.parse(JSON.stringify(defaults));for(const id of Object.keys(roles))if(names[value.assignments?.[id]])out.assignments[id]=value.assignments[id];for(const id of Object.keys(names)){const v=value.presets?.[id]||{},d=out.presets[id];Object.assign(d,{size:clamp(v.size,5,32,d.size),align:v.align==='center'?'center':v.align==='left'?'left':d.align,padding:clamp(v.padding,0,40,d.padding),offset:clamp(v.offset,-60,60,d.offset),uppercase:v.uppercase===true,color:/^#[0-9a-f]{6}$/i.test(v.color)?v.color:d.color})}return out}
 let state=normalize();try{state=normalize(JSON.parse(localStorage.getItem(key)||'{}'))}catch{}
 const api=window.PeninsulaText={names,roles,defaults,normalize,get state(){return state},get(role){return state.presets[state.assignments[role]||role]||state.presets.technical},update(value){state=normalize(value);try{localStorage.setItem(key,JSON.stringify(state))}catch{}window.dispatchEvent(new Event('text-presets-change'))},format(s,role){s=String(s);return api.get(role).uppercase?s.toLocaleUpperCase('ru'):s},metrics(role,fonts){const s=api.get(role),f=fonts[s.size>=16?'unifont':'cozette'];return {s,f,ratio:s.size/f.height,step:s.size+2}},measure(s,role,fonts){const {f,ratio}=api.metrics(role,fonts);return [...api.format(s,role)].reduce((n,ch)=>n+Math.max(1,Math.round((f.glyphs[ch]?.w||6)*ratio)),0)},lines(s,w,role,fonts){const result=[];for(const para of api.format(s,role).split('\n')){let line='';for(const word of para.split(/\s+/)){if(line&&api.measure(line+' '+word,role,fonts)>w){result.push(line);line=''}for(const ch of (line?' ':'')+word){if(line&&api.measure(line+ch,role,fonts)>w){result.push(line);line=''}line+=ch}}result.push(line)}return result},line(c,text,x,y,role,fonts,align){const {s,f,ratio}=api.metrics(role,fonts);if(!f.image)return;const cache=f.presetAtlases||(f.presetAtlases=new Map());let atlas=cache.get(s.color);if(!atlas){atlas=document.createElement('canvas');atlas.width=f.image.width;atlas.height=f.image.height;const g=atlas.getContext('2d');g.drawImage(f.image,0,0);g.globalCompositeOperation='source-in';g.fillStyle=s.color;g.fillRect(0,0,atlas.width,atlas.height);if(cache.size>32)cache.clear();cache.set(s.color,atlas)}text=api.format(text,role);align=align||s.align;let ox=Math.round(x-(align==='center'?api.measure(text,role,fonts)/2:align==='right'?api.measure(text,role,fonts):0));c.imageSmoothingEnabled=false;for(const ch of text){const g=f.glyphs[ch]||f.glyphs['?'];if(g&&ch!==' ')c.drawImage(atlas,g.x,g.y,10,f.height,ox,Math.round(y),Math.max(1,Math.round(10*ratio)),s.size);ox+=Math.max(1,Math.round((g?.w||6)*ratio))}},block(c,text,x,y,w,h,role,fonts){const {s,step}=api.metrics(role,fonts),pad=Math.min(s.padding,Math.max(0,Math.floor((w-1)/2)));const rows=api.lines(text,w-pad*2,role,fonts);c.save();c.beginPath();c.rect(Math.round(x),Math.round(y),Math.round(w),Math.round(h));c.clip();rows.forEach((line,i)=>api.line(c,line,s.align==='center'?x+w/2:x+pad,y+s.offset+i*step,role,fonts));c.restore();return rows.length}};
 window.addEventListener('storage',e=>{if(e.key===key){try{state=normalize(JSON.parse(e.newValue||'{}'));window.dispatchEvent(new Event('text-presets-change'))}catch{}}});
})();
